import{z as u,x as E,o as d,c as p,q as i,j as o,D as a,d as t,s as r,S as l,b as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"udev 与热插拔","description":"","frontmatter":{"title":"udev 与热插拔","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/udev-hotplug.md","filePath":"cs/udev-hotplug.md","lastUpdated":1791063341000}'),v={name:"cs/udev-hotplug.md"};function c(B,e,A,m,h,f){const n=E("Mermaid");return d(),p("div",null,[e[2]||(e[2]=i('<h1 id="udev-与热插拔" tabindex="-1">udev 与热插拔 <a class="header-anchor" href="#udev-与热插拔" aria-label="Permalink to &quot;udev 与热插拔&quot;">​</a></h1><div class="epigraph"><p>内核通过 uevent 把设备增删广播出去；udev 在用户态命名节点、加载固件、跑规则，而不把策略写死在内核。</p><footer>—— 据 Linux hotplug/uevent 文档；systemd-udevd；[设备模型](/cs/device-model-binding) 为先修</footer></div><p><a href="/cs/chardev-ioctl">上一课</a>留下的缺口接到本课。 <a href="/cs/device-nodes">设备节点</a> 要有名字。<a href="/cs/device-model-binding">probe</a> 产生 <strong>uevent</strong>。缺口是 udev：规则、<code>/dev</code> 动态、固件加载。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核发 netlink uevent。udev：匹配 ATTR、创建 <code>/dev/disk/by-uuid</code>、<code>RUN</code> 脚本。缺口：与 <a href="/cs/initramfs-pivot">initramfs</a> 里的早期 udev；规则错误可改权限导致安全问题。本课不把所有规则写成发行版文档。</p><p><span class="marginnote">「uevent」就是内核在设备插入或拔出时向用户态发的广播消息，里面带子系统、厂商 ID 等属性；udev 收到后按规则决定这个设备叫什么名字、要不要加载固件。</span></p><p><span class="marginnote">devtmpfs 先由内核造节点，udev 再改名/链。固件：<code>/lib/firmware</code> 经 sysfs 请求。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>uevent → udevd 匹配 → 节点与 systemd 设备单元。对照 <a href="/cs/inotify">inotify</a>：一个文件树，一个设备树。对照 netns：udev 通常在初始 ns。对照 <a href="/cs/scsi-stack">SCSI</a>：扫描完成才有盘事件。</p>',9)),(d(),o(l,null,{default:a(()=>[r(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%86%85%E6%A0%B8%20uevent%22%5D%20--%3E%20U%5B%22udevd%22%5D%0A%20%20U%20--%3E%20DEV%5B%22%2Fdev%20%E8%8A%82%E7%82%B9%E4%B8%8E%E7%AC%A6%E5%8F%B7%E9%93%BE%22%5D%0A%20%20U%20--%3E%20FW%5B%22%E5%8A%A0%E8%BD%BD%E5%9B%BA%E4%BB%B6%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=s("p",null,"一条 uevent 是如何被决定成最终节点名的——逐条规则匹配直到命中：",-1)),(d(),o(l,null,{default:a(()=>[r(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22uevent%20%E5%88%B0%E8%BE%BE%20udevd%22%5D%20--%3E%20READ%5B%22%E8%AF%BB%20SUBSYSTEM%20%E4%B8%8E%20ATTR%22%5D%0A%20%20READ%20--%3E%20LOOP%7B%22%E5%91%BD%E4%B8%AD%E4%B8%80%E6%9D%A1%E8%A7%84%E5%88%99%EF%BC%9F%22%7D%0A%20%20LOOP%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20ACT%5B%22%E5%BA%94%E7%94%A8%20NAME%3D%20%E4%B8%8E%20SYMLINK%3D%22%5D%0A%20%20ACT%20--%3E%20RUN%5B%22%E6%89%A7%E8%A1%8C%20RUN%3D%20%E8%84%9A%E6%9C%AC%22%5D%0A%20%20RUN%20--%3E%20DONE%5B%22%E8%8A%82%E7%82%B9%E8%90%BD%E7%9B%98%22%5D%0A%20%20LOOP%20--%3E%7C%22%E9%81%8D%E5%8E%86%E5%AE%8C%E6%97%A0%E5%91%BD%E4%B8%AD%22%7C%20DEF%5B%22%E4%BF%9D%E7%95%99%20devtmpfs%20%E9%BB%98%E8%AE%A4%E5%90%8D%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=i('<p>udev 把命名策略放用户态，内核只报事实。这是热插拔可管理的原因。不要写成桌面自动挂载广告。与 <a href="/cs/lsm-selinux">LSM</a>：新节点的标签要规则配合。</p><p><span class="marginnote">数字实例：插一个 U 盘，设备本身加上分区（sda、sda1、sda2…）会各自触发 add、bind 等多条 uevent，一次插入轻松超过十条；udev 对同一设备串行处理，就是防止 sda1 还没命名就有脚本抢先去挂载。</span></p><p>风暴：USB 枚举可打满 udev 队列。</p><p>实现上：规则里的 NAME= 与 devtmpfs 冲突时以策略为准，写错会把盘节点改成不可预测的名字。固件加载失败则设备 probe 失败，表现为「没有网卡」。 读法上只引用<a href="/cs/chardev-ioctl">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>udev 与热插拔</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 TAG。不保证容器内 mknod 与宿主机 udev 的关系写完。下一课整机睡眠：挂起与恢复。</p><p><span class="marginnote">常见误区：初学者容易以为 <code>/dev</code> 下的名字是内核定的。devtmpfs 只给默认名，最终名字由用户态 udev 规则决定——规则写错可能把磁盘节点改成猜不到的名字，mount 脚本跟着全部失灵。</span></p><p>版本字段会变，课序钉的是机制对象「udev 与热插拔」，不是某一主线内核的结构体名。 后课默认：设备名由 uevent+udev 策略产生。休眠时驱动如何冻结，下一课 suspend。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>uevent 出核，udev 命名并加载固件。</li><li>策略在用户态规则，不在驱动里写死。</li><li>挂起恢复是下一课。</li><li>出处：udev；uevent；systemd-udevd。</li></ul>',12))])}const T=u(v,[["render",c]]);export{_ as __pageData,T as default};
